import numpy as np
from PIL import Image, ImageFilter
im = Image.open('radiograph.jpg').convert('L')
small = np.asarray(im.filter(ImageFilter.GaussianBlur(8))).astype(np.float32)
large = np.asarray(im.filter(ImageFilter.GaussianBlur(45))).astype(np.float32)
resp = large-small
resp = (resp-resp.min())/(resp.max()-resp.min())*255
H,W = resp.shape
pct = np.percentile(resp, 99.5)
peaks=[]
for y in range(0,H,6):
    for x in range(0,W,6):
        v=resp[y,x]
        if v>pct: peaks.append((float(v),int(x),int(y)))
peaks.sort(reverse=True)
out=[]
for v,x,y in peaks:
    if all((x-x2)**2+(y-y2)**2 > 70**2 for _,x2,y2 in out): out.append((v,x,y))
print('top dark blobs:')
for v,x,y in out[:20]: print(round(x/2473,3), round(y/1252,3), round(v,1))
